CREATE OR REPLACE FUNCTION public.calculate_annual_leave_accruals()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    r record;
    years_worked integer;
    days_to_add numeric;
BEGIN
    -- Sadece bugün işe girişinin yıl dönümü olan (ay ve gün eşleşen) kişileri bul
    FOR r IN 
        SELECT user_id, hire_date 
        FROM public.user_leave_balances
        WHERE EXTRACT(month FROM hire_date) = EXTRACT(month FROM CURRENT_DATE)
          AND EXTRACT(day FROM hire_date) = EXTRACT(day FROM CURRENT_DATE)
          AND hire_date < CURRENT_DATE -- Bugün işe ilk kez girenleri es geç
    LOOP
        -- Kaçıncı yılını doldurdu?
        years_worked := EXTRACT(year FROM CURRENT_DATE) - EXTRACT(year FROM r.hire_date);
        
        -- İş Kanunu Oranları: 
        -- 1 yıldan 5 yıla kadar (5 dahil) -> 14 Gün
        -- 5 yıldan fazla 15 yıldan az (6-14 yıl arası) -> 20 Gün
        -- 15 yıl (dahil) ve daha fazla -> 26 Gün
        IF years_worked >= 1 AND years_worked <= 5 THEN
            days_to_add := 14;
        ELSIF years_worked >= 6 AND years_worked <= 14 THEN
            days_to_add := 20;
        ELSIF years_worked >= 15 THEN
            days_to_add := 26;
        ELSE
            days_to_add := 0;
        END IF;

        -- Hak edişi bakiyeye ekle
        IF days_to_add > 0 THEN
            UPDATE public.user_leave_balances
            SET earned_annual_leave = earned_annual_leave + days_to_add,
                updated_at = NOW()
            WHERE user_id = r.user_id;
        END IF;
    END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.complete_petition_review(p_review_task_id text, p_result text, p_note text DEFAULT NULL::text, p_revised_document_id text DEFAULT NULL::text, p_revised_document_name text DEFAULT NULL::text, p_revised_document_url text DEFAULT NULL::text, p_revised_document_storage_path text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_review public.tasks%ROWTYPE;
    v_source public.tasks%ROWTYPE;
    v_review_details jsonb;
    v_source_details jsonb;
    v_history jsonb;
    v_source_id text;
    v_actor_id text := auth.uid()::text;
    v_actor_role text;
    v_actor_name text;
    v_actor_email text;
    v_round integer;
    v_has_revised_document boolean := false;
    v_revised_document jsonb := NULL;
    v_replaced_documents jsonb := '[]'::jsonb;
    v_source_tx_id text;
BEGIN
    IF v_actor_id IS NULL THEN
        RAISE EXCEPTION 'Oturum bulunamadı.';
    END IF;

    IF p_result NOT IN ('approved', 'revision_requested') THEN
        RAISE EXCEPTION 'Geçersiz kontrol sonucu: %', p_result;
    END IF;

    IF p_result = 'revision_requested' AND COALESCE(btrim(p_note), '') = '' THEN
        RAISE EXCEPTION 'Düzeltme notu zorunludur.';
    END IF;

    v_has_revised_document :=
        COALESCE(btrim(p_revised_document_id), '') <> ''
        OR COALESCE(btrim(p_revised_document_name), '') <> ''
        OR COALESCE(btrim(p_revised_document_url), '') <> ''
        OR COALESCE(btrim(p_revised_document_storage_path), '') <> '';

    IF v_has_revised_document AND p_result <> 'revision_requested' THEN
        RAISE EXCEPTION 'Revize dilekçe yalnız Düzeltme İste işlemi ile yüklenebilir.';
    END IF;

    IF v_has_revised_document AND (
        COALESCE(btrim(p_revised_document_id), '') = ''
        OR COALESCE(btrim(p_revised_document_name), '') = ''
        OR COALESCE(btrim(p_revised_document_url), '') = ''
    ) THEN
        RAISE EXCEPTION 'Revize dilekçe bilgileri eksik.';
    END IF;

    SELECT role, display_name, email
      INTO v_actor_role, v_actor_name, v_actor_email
    FROM public.users
    WHERE id = v_actor_id;

    SELECT * INTO v_review
    FROM public.tasks
    WHERE id = p_review_task_id
    FOR UPDATE;

    IF NOT FOUND OR v_review.task_type_id <> '83' THEN
        RAISE EXCEPTION 'Dilekçe Kontrol işi bulunamadı: %', p_review_task_id;
    END IF;

    IF v_review.assigned_to IS DISTINCT FROM v_actor_id
       AND COALESCE(v_actor_role, '') NOT IN ('admin','superadmin') THEN
        RAISE EXCEPTION 'Bu kontrol işini sonuçlandırma yetkiniz yok.';
    END IF;

    IF v_review.status = 'completed' THEN
        RETURN jsonb_build_object(
            'review_task_id', p_review_task_id,
            'source_task_id', v_review.details ->> 'source_task_id',
            'result', v_review.details ->> 'review_result',
            'already_completed', true,
            'replaced_documents', '[]'::jsonb
        );
    END IF;

    v_review_details := COALESCE(v_review.details, '{}'::jsonb);
    v_source_id := COALESCE(v_review_details ->> 'source_task_id', v_review_details ->> 'parent_task_id');

    IF v_source_id IS NULL THEN
        RAISE EXCEPTION 'Kontrol işinde kaynak iş bağlantısı bulunamadı.';
    END IF;

    SELECT * INTO v_source
    FROM public.tasks
    WHERE id = v_source_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Kaynak iş bulunamadı: %', v_source_id;
    END IF;

    v_source_details := COALESCE(v_source.details, '{}'::jsonb);

    IF COALESCE(v_source_details ->> 'petition_review_active_task_id', '') <> p_review_task_id THEN
        RAISE EXCEPTION 'Bu kontrol işi kaynak işin aktif kontrol turu değildir.';
    END IF;

    v_round := COALESCE((v_review_details ->> 'review_round')::integer, 1);

    -- Kontrol görevlisi revize dilekçe yüklediyse:
    -- * mevcut aktif petition belgelerini kaynak task'tan kaldır
    -- * aynı URL'lerin transaction_documents kayıtlarını kaldır
    -- * yeni belgeyi kaynak task'ın aktif petition belgesi olarak ekle
    -- * tasks.transaction_id alanına güvenmek yerine doğru transaction'ı
    --   task_id + transaction_type_id eşleşmesi ile bul.
    IF v_has_revised_document THEN
        SELECT COALESCE(
            jsonb_agg(
                jsonb_build_object(
                    'id', td.id,
                    'name', td.document_name,
                    'url', td.document_url
                )
                ORDER BY td.uploaded_at NULLS LAST, td.id
            ),
            '[]'::jsonb
        )
        INTO v_replaced_documents
        FROM public.task_documents td
        WHERE td.task_id = v_source_id
          AND td.document_type = 'petition';

        DELETE FROM public.transaction_documents txd
        WHERE txd.document_url IN (
            SELECT td.document_url
            FROM public.task_documents td
            WHERE td.task_id = v_source_id
              AND td.document_type = 'petition'
              AND td.document_url IS NOT NULL
        );

        DELETE FROM public.task_documents
        WHERE task_id = v_source_id
          AND document_type = 'petition';

        INSERT INTO public.task_documents (
            id,
            task_id,
            document_name,
            document_url,
            document_type
        )
        VALUES (
            p_revised_document_id::uuid,
            v_source_id,
            p_revised_document_name,
            p_revised_document_url,
            'petition'
        );

        SELECT tr.id
          INTO v_source_tx_id
        FROM public.transactions tr
        WHERE tr.task_id = v_source_id
          AND tr.transaction_type_id = v_source.task_type_id
        ORDER BY tr.created_at DESC NULLS LAST, tr.transaction_date DESC NULLS LAST
        LIMIT 1;

        IF v_source_tx_id IS NOT NULL THEN
            INSERT INTO public.transaction_documents (
                transaction_id,
                document_name,
                document_url,
                document_type
            )
            VALUES (
                v_source_tx_id,
                p_revised_document_name,
                p_revised_document_url,
                'petition'
            );
        END IF;

        v_revised_document := jsonb_build_object(
            'id', p_revised_document_id,
            'name', p_revised_document_name,
            'url', p_revised_document_url,
            'storage_path', NULLIF(btrim(p_revised_document_storage_path), ''),
            'review_task_id', p_review_task_id,
            'round', v_round,
            'uploaded_by', v_actor_id,
            'uploaded_by_name', COALESCE(v_actor_name, v_actor_email, v_actor_id),
            'uploaded_at', now()
        );
    END IF;

    v_review_details := v_review_details || jsonb_build_object(
        'review_result', p_result,
        'review_note', CASE WHEN p_result = 'revision_requested' THEN btrim(p_note) ELSE NULL END,
        'reviewed_by', v_actor_id,
        'reviewed_by_name', COALESCE(v_actor_name, v_actor_email, v_actor_id),
        'reviewed_at', now(),
        'revised_document', v_revised_document
    );

    UPDATE public.tasks
    SET status = 'completed',
        details = v_review_details,
        updated_at = now()
    WHERE id = p_review_task_id;

    IF jsonb_typeof(v_source_details -> 'petition_review_history') = 'array' THEN
        v_history := v_source_details -> 'petition_review_history';
    ELSE
        v_history := '[]'::jsonb;
    END IF;

    v_history := v_history || jsonb_build_array(jsonb_build_object(
        'review_task_id', p_review_task_id,
        'round', v_round,
        'result', p_result,
        'note', CASE WHEN p_result = 'revision_requested' THEN btrim(p_note) ELSE NULL END,
        'reviewed_by', v_actor_id,
        'reviewed_by_name', COALESCE(v_actor_name, v_actor_email, v_actor_id),
        'reviewed_at', now(),
        'revised_document', v_revised_document,
        'replaced_documents', v_replaced_documents
    ));

    -- Eski turdan kalmış "son revize belge" bilgisini temizle; bu turda yeni bir
    -- revize belge varsa aşağıda tekrar eklenir.
    v_source_details := v_source_details
        - 'petition_review_active_task_id'
        - 'petition_review_revised_document';

    v_source_details := v_source_details || jsonb_build_object(
        'petition_review_status', p_result,
        'petition_review_last_note', CASE WHEN p_result = 'revision_requested' THEN btrim(p_note) ELSE NULL END,
        'petition_review_last_reviewer_id', v_actor_id,
        'petition_review_last_reviewer_name', COALESCE(v_actor_name, v_actor_email, v_actor_id),
        'petition_review_last_reviewed_at', now(),
        'petition_review_history', v_history
    );

    IF v_revised_document IS NOT NULL THEN
        v_source_details := v_source_details || jsonb_build_object(
            'petition_review_revised_document', v_revised_document
        );
    END IF;

    UPDATE public.tasks
    SET details = v_source_details,
        updated_at = now()
    WHERE id = v_source_id;

    INSERT INTO public.task_history(task_id, action, user_id, details)
    VALUES
        (
            p_review_task_id,
            CASE WHEN p_result = 'approved' THEN 'Dilekçe onaylandı' ELSE 'Dilekçede düzeltme istendi' END,
            v_actor_id,
            jsonb_build_object(
                'result', p_result,
                'note', p_note,
                'revised_document', v_revised_document
            )
        ),
        (
            v_source_id,
            CASE
                WHEN p_result = 'approved' THEN 'Dilekçe kontrolü onaylandı'
                WHEN v_revised_document IS NOT NULL THEN 'Dilekçe kontrolünde düzeltme istendi ve revize dilekçe yüklendi'
                ELSE 'Dilekçe kontrolünde düzeltme istendi'
            END,
            v_actor_id,
            jsonb_build_object(
                'review_task_id', p_review_task_id,
                'result', p_result,
                'note', p_note,
                'revised_document', v_revised_document
            )
        );

    RETURN jsonb_build_object(
        'review_task_id', p_review_task_id,
        'source_task_id', v_source_id,
        'result', p_result,
        'note', CASE WHEN p_result = 'revision_requested' THEN btrim(p_note) ELSE NULL END,
        'revised_document', v_revised_document,
        'replaced_documents', v_replaced_documents,
        'already_completed', false
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.evreka_touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
    new.updated_at = now();
    return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.evreka_validate_citable_proposition()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
    parent_verified boolean;
    parent_citable boolean;
    parent_status text;
begin
    if new.citable = true then
        select a.verified, a.citable, a.status
        into parent_verified, parent_citable, parent_status
        from public.legal_authorities a
        where a.id = new.authority_id;

        if coalesce(parent_verified, false) <> true
           or coalesce(parent_citable, false) <> true
           or coalesce(parent_status, '') <> 'verified'
        then
            raise exception 'Citable proposition için parent authority verified=true, citable=true ve status=verified olmalıdır.';
        end if;
    end if;
    return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.export_mini_db()
 RETURNS json
 LANGUAGE plpgsql
AS $function$
DECLARE
    tbl record;
    result jsonb := '{}'::jsonb;
    rows jsonb;
BEGIN
    -- public şemasındaki tüm tabloları dön
    FOR tbl IN 
        SELECT table_name 
        FROM information_schema.tables 
        WHERE table_schema = 'public' AND table_type = 'BASE TABLE'
    LOOP
        -- Her tablodan 3 kayıt çek ve JSON'a çevir
        EXECUTE format('SELECT COALESCE(jsonb_agg(row_to_json(t)), ''[]''::jsonb) FROM (SELECT * FROM public.%I LIMIT 3) t', tbl.table_name)
        INTO rows;
        
        -- Sonuç objesine tablo adıyla birlikte ekle
        result := jsonb_set(result, ARRAY[tbl.table_name], rows);
    END LOOP;
    
    RETURN result;
END;
$function$

