CREATE OR REPLACE FUNCTION public.send_petition_for_review(p_source_task_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_source public.tasks%ROWTYPE;
    v_source_details jsonb;
    v_actor_id text := auth.uid()::text;
    v_actor_role text;
    v_actor_email text;
    v_controller_id text;
    v_controller_name text;
    v_controller_email text;
    v_fallback_id constant text := '28f07d5d-f1c6-456f-8b4b-3bb8226b5253';
    v_petition_docs jsonb;
    v_review_id text;
    v_existing_review_id text;
    v_next_num numeric;
    v_round integer;
    v_round_text text;
BEGIN
    IF v_actor_id IS NULL THEN
        RAISE EXCEPTION 'Oturum bulunamadı.';
    END IF;

    SELECT role, email
      INTO v_actor_role, v_actor_email
    FROM public.users
    WHERE id = v_actor_id;

    SELECT * INTO v_source
    FROM public.tasks
    WHERE id = p_source_task_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Kaynak iş bulunamadı: %', p_source_task_id;
    END IF;

    IF v_source.task_type_id NOT IN ('1','7','19','20','37','38','39') THEN
        RAISE EXCEPTION 'Bu iş tipi dilekçe kontrol akışına dahil değildir: %', v_source.task_type_id;
    END IF;

    IF COALESCE(v_source.status, '') IN ('completed','cancelled') THEN
        RAISE EXCEPTION 'Tamamlanmış veya iptal edilmiş iş dilekçe kontrolüne gönderilemez.';
    END IF;

    IF v_source.assigned_to IS DISTINCT FROM v_actor_id
       AND COALESCE(v_actor_role, '') NOT IN ('admin','superadmin') THEN
        RAISE EXCEPTION 'Bu dilekçeyi kontrole gönderme yetkiniz yok.';
    END IF;

    IF v_source.task_owner_id IS NULL THEN
        RAISE EXCEPTION 'Kaynak işin task_owner_id bilgisi yok. Kontrol görevlisi belirlenemedi.';
    END IF;

    v_source_details := COALESCE(v_source.details, '{}'::jsonb);

    -- Aynı kaynak iş halihazırda kontroldeyse mevcut aktif kontrol işini döndür.
    -- Böylece çift tıklama / eşzamanlı istek ikinci bir 83 oluşturmaz.
    IF COALESCE(v_source_details ->> 'petition_review_status', '') = 'in_review'
       AND COALESCE(v_source_details ->> 'petition_review_active_task_id', '') <> '' THEN
        v_existing_review_id := v_source_details ->> 'petition_review_active_task_id';

        IF EXISTS (
            SELECT 1
            FROM public.tasks t
            WHERE t.id = v_existing_review_id
              AND t.task_type_id = '83'
              AND COALESCE(t.status, '') NOT IN ('completed','cancelled')
        ) THEN
            SELECT u.display_name, u.email
              INTO v_controller_name, v_controller_email
            FROM public.tasks t
            LEFT JOIN public.users u ON u.id = t.assigned_to
            WHERE t.id = v_existing_review_id;

            RETURN jsonb_build_object(
                'review_task_id', v_existing_review_id,
                'status', 'in_review',
                'assigned_to_name', COALESCE(v_controller_name, v_controller_email, ''),
                'already_exists', true
            );
        END IF;
    END IF;

    IF COALESCE(v_source_details ->> 'petition_review_status', '') <> 'ready' THEN
        RAISE EXCEPTION 'Dilekçe kontrole gönderilmeye hazır durumda değil.';
    END IF;

    SELECT jsonb_agg(
        jsonb_build_object(
            'id', td.id,
            'name', td.document_name,
            'url', td.document_url
        ) ORDER BY td.uploaded_at NULLS LAST, td.id
    )
    INTO v_petition_docs
    FROM public.task_documents td
    WHERE td.task_id = p_source_task_id
      AND td.document_type = 'petition';

    IF v_petition_docs IS NULL OR jsonb_array_length(v_petition_docs) = 0 THEN
        RAISE EXCEPTION 'Kontrole gönderilecek dilekçe belgesi bulunamadı.';
    END IF;

    -- Aynı kaynak iş için açık bir kontrol işi varsa ikinci kez oluşturma.
    SELECT t.id
      INTO v_existing_review_id
    FROM public.tasks t
    WHERE t.task_type_id = '83'
      AND t.details ->> 'source_task_id' = p_source_task_id
      AND COALESCE(t.status, '') NOT IN ('completed','cancelled')
    ORDER BY t.created_at DESC
    LIMIT 1;

    IF v_existing_review_id IS NOT NULL THEN
        v_source_details := v_source_details || jsonb_build_object(
            'petition_review_status', 'in_review',
            'petition_review_active_task_id', v_existing_review_id
        );
        UPDATE public.tasks
        SET details = v_source_details, updated_at = now()
        WHERE id = p_source_task_id;

        RETURN jsonb_build_object(
            'review_task_id', v_existing_review_id,
            'status', 'in_review',
            'already_exists', true
        );
    END IF;

    -- Müvekkil bazlı kontrol görevlisi; geçersiz/pasif/client ise fallback.
    SELECT u.id, u.display_name, u.email
      INTO v_controller_id, v_controller_name, v_controller_email
    FROM public.persons p
    JOIN public.users u ON u.id = p.petition_controller_user_id
    WHERE p.id = v_source.task_owner_id
      AND u.disabled IS NOT TRUE
      AND u.role IS DISTINCT FROM 'client'
    LIMIT 1;

    IF v_controller_id IS NULL THEN
        SELECT u.id, u.display_name, u.email
          INTO v_controller_id, v_controller_name, v_controller_email
        FROM public.users u
        WHERE u.id = v_fallback_id
          AND u.disabled IS NOT TRUE
          AND u.role IS DISTINCT FROM 'client'
        LIMIT 1;
    END IF;

    IF v_controller_id IS NULL THEN
        RAISE EXCEPTION 'Aktif bir kontrol görevlisi veya fallback kullanıcı bulunamadı.';
    END IF;

    v_round_text := v_source_details ->> 'petition_review_round';
    IF v_round_text ~ '^[0-9]+$' THEN
        v_round := v_round_text::integer + 1;
    ELSE
        v_round := 1;
    END IF;

    -- Standart task counter'ını satır kilidiyle ilerlet.
    INSERT INTO public.counters(id, last_id)
    VALUES ('tasks', 0)
    ON CONFLICT (id) DO NOTHING;

    SELECT COALESCE(last_id, 0)
      INTO v_next_num
    FROM public.counters
    WHERE id = 'tasks'
    FOR UPDATE;

    LOOP
        v_next_num := v_next_num + 1;
        v_review_id := trunc(v_next_num)::bigint::text;
        EXIT WHEN NOT EXISTS (SELECT 1 FROM public.tasks WHERE id = v_review_id);
    END LOOP;

    UPDATE public.counters
    SET last_id = v_next_num
    WHERE id = 'tasks';

    INSERT INTO public.tasks (
        id,
        title,
        description,
        task_type_id,
        status,
        priority,
        ip_record_id,
        task_owner_id,
        created_by,
        assigned_to,
        details,
        created_at,
        updated_at
    ) VALUES (
        v_review_id,
        'Dilekçe Kontrol - ' || COALESCE(NULLIF(v_source.title, ''), '#' || p_source_task_id),
        '#' || p_source_task_id || ' numaralı işe ait dilekçenin kontrolü.',
        '83',
        'open',
        COALESCE(v_source.priority, 'normal'),
        v_source.ip_record_id,
        v_source.task_owner_id,
        v_actor_id,
        v_controller_id,
        jsonb_build_object(
            'source_task_id', p_source_task_id,
            'parent_task_id', p_source_task_id,
            'petition_documents', v_petition_docs,
            'review_round', v_round,
            'requested_by', v_actor_id,
            'requested_by_email', v_actor_email,
            'requested_at', now(),
            'review_result', 'pending',
            'assigned_to_email', v_controller_email
        ),
        now(),
        now()
    );

    v_source_details := v_source_details || jsonb_build_object(
        'petition_review_status', 'in_review',
        'petition_review_active_task_id', v_review_id,
        'petition_review_round', v_round,
        'petition_review_requested_at', now(),
        'petition_review_requested_by', v_actor_id
    );

    UPDATE public.tasks
    SET details = v_source_details,
        updated_at = now()
    WHERE id = p_source_task_id;

    INSERT INTO public.task_history(task_id, action, user_id, details)
    VALUES
        (p_source_task_id, 'Dilekçe kontrole gönderildi', v_actor_id,
            jsonb_build_object('review_task_id', v_review_id, 'controller_user_id', v_controller_id)),
        (v_review_id, 'Dilekçe kontrol işi oluşturuldu', v_actor_id,
            jsonb_build_object('source_task_id', p_source_task_id, 'review_round', v_round));

    RETURN jsonb_build_object(
        'review_task_id', v_review_id,
        'status', 'in_review',
        'round', v_round,
        'assigned_to', v_controller_id,
        'assigned_to_name', COALESCE(v_controller_name, v_controller_email, v_controller_id),
        'assigned_to_email', v_controller_email,
        'already_exists', false
