CREATE OR REPLACE FUNCTION public.sync_petition_review_readiness(p_source_task_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_task public.tasks%ROWTYPE;
    v_details jsonb;
    v_has_petition boolean;
    v_actor_id text := auth.uid()::text;
    v_actor_role text;
    v_status text;
BEGIN
    IF v_actor_id IS NULL THEN
        RAISE EXCEPTION 'Oturum bulunamadı.';
    END IF;

    SELECT role INTO v_actor_role
    FROM public.users
    WHERE id = v_actor_id;

    SELECT * INTO v_task
    FROM public.tasks
    WHERE id = p_source_task_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Kaynak iş bulunamadı: %', p_source_task_id;
    END IF;

    IF v_task.task_type_id NOT IN ('1','7','19','20','37','38','39') THEN
        RAISE EXCEPTION 'Bu iş tipi dilekçe kontrol akışına dahil değildir: %', v_task.task_type_id;
    END IF;

    IF v_task.assigned_to IS DISTINCT FROM v_actor_id
       AND COALESCE(v_actor_role, '') NOT IN ('admin','superadmin') THEN
        RAISE EXCEPTION 'Bu iş için dilekçe kontrol durumunu değiştirme yetkiniz yok.';
    END IF;

    v_details := COALESCE(v_task.details, '{}'::jsonb);
    v_status := v_details ->> 'petition_review_status';

    SELECT EXISTS (
        SELECT 1
        FROM public.task_documents td
        WHERE td.task_id = p_source_task_id
          AND td.document_type = 'petition'
    ) INTO v_has_petition;

    -- Aktif kontrol turu devam ederken durum değiştirilmez.
    IF v_status = 'in_review' THEN
        RETURN jsonb_build_object('status', 'in_review', 'has_petition', v_has_petition);
    END IF;

    IF v_has_petition THEN
        v_details := v_details || jsonb_build_object(
            'petition_review_status', 'ready',
            'petition_review_ready_at', now(),
            'petition_review_ready_by', v_actor_id
        );
    ELSIF v_status = 'ready' THEN
        v_details := v_details - 'petition_review_status' - 'petition_review_ready_at' - 'petition_review_ready_by';
    END IF;

    UPDATE public.tasks
    SET details = v_details,
        updated_at = now()
    WHERE id = p_source_task_id;

    RETURN jsonb_build_object(
        'status', v_details ->> 'petition_review_status',
        'has_petition', v_has_petition
    );
END;
$function$

