CREATE OR REPLACE FUNCTION public.trg_assign_portfolio_manager_on_task_open()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_is_portfolio_managed boolean := false;
    v_assignee_id text;
    v_assignee_email text;
    v_default_user_id CONSTANT text := '28f07d5d-f1c6-456f-8b4b-3bb8226b5253'; -- Muhammed Özcan
BEGIN
    SELECT EXISTS (
        SELECT 1
        FROM public.task_assignments ta
        WHERE ta.id = NEW.task_type_id
          AND ta.assignment_type = 'portfolio_manager'
    )
    INTO v_is_portfolio_managed;

    IF NOT v_is_portfolio_managed THEN
        RETURN NEW;
    END IF;

    -- INSERT: yalnız OPEN oluşturuluyorsa çalışır.
    -- UPDATE: yalnız başka bir statüden OPEN'a geçiyorsa çalışır.
    -- OPEN -> OPEN güncellemelerinde manuel reassignment korunur.
    IF TG_OP = 'INSERT' THEN
        IF NEW.status IS DISTINCT FROM 'open' THEN
            RETURN NEW;
        END IF;
    ELSIF TG_OP = 'UPDATE' THEN
        IF NEW.status IS DISTINCT FROM 'open'
           OR OLD.status IS NOT DISTINCT FROM 'open' THEN
            RETURN NEW;
        END IF;
    END IF;

    -- task_owner_id'nin aktif, client olmayan portföy yöneticisini bul.
    SELECT u.id, u.email
      INTO v_assignee_id, v_assignee_email
    FROM public.persons p
    JOIN public.users u
      ON u.id = p.portfolio_manager_user_id
    WHERE p.id = NEW.task_owner_id
      AND u.disabled IS NOT TRUE
      AND u.role IS DISTINCT FROM 'client'
    LIMIT 1;

    -- Portföy yöneticisi yoksa / geçersizse Muhammed Özcan fallback.
    IF v_assignee_id IS NULL THEN
        SELECT u.id, u.email
          INTO v_assignee_id, v_assignee_email
        FROM public.users u
        WHERE u.id = v_default_user_id
          AND u.disabled IS NOT TRUE
          AND u.role IS DISTINCT FROM 'client'
        LIMIT 1;
    END IF;

    -- Preflight kullanıcının varlığını doğrular; yine de son güvenlik ağı.
    -- Fallback sonradan pasifleştirilmişse mevcut assigned_to değerini bozma.
    IF v_assignee_id IS NULL THEN
        RAISE WARNING
            'Portföy yöneticisi ataması yapılamadı. task_id=%, owner=%, type=%',
            NEW.id, NEW.task_owner_id, NEW.task_type_id;
        RETURN NEW;
    END IF;

    NEW.assigned_to := v_assignee_id;

    NEW.details := jsonb_set(
        COALESCE(NEW.details, '{}'::jsonb),
        '{assigned_to_email}',
        to_jsonb(COALESCE(v_assignee_email, '')),
        true
    );

    NEW.details := jsonb_set(
        COALESCE(NEW.details, '{}'::jsonb),
        '{assignment_mode}',
        to_jsonb('portfolio_manager'::text),
        true
    );

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.trg_cleanup_transaction_on_rejection()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
-- Eğer statü "Onay Bekliyor"dan "Kapalı/Reddedildi" statülerinden birine geçerse
IF OLD.status IN ('awaiting_client_approval', 'awaiting-approval') 
    AND NEW.status IN ('client_approval_closed', 'client_no_response_closed') THEN
    
    -- A) Önce bu göreve ait ana işlemlerin alt (child) işlemlerini sil
    DELETE FROM transactions WHERE parent_id IN (
        SELECT id FROM transactions WHERE task_id = NEW.id
    );
    
    -- B) Ardından ana işlemi (transaction) sil
    DELETE FROM transactions WHERE task_id = NEW.id;

END IF;

RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.trg_guard_petition_review_workflow()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
    IF NEW.status IS DISTINCT FROM OLD.status THEN
        IF NEW.task_type_id IN ('1','7','19','20','37','38','39')
           AND NEW.status IN ('completed','cancelled','archived')
           AND COALESCE(OLD.details ->> 'petition_review_status', '') = 'in_review' THEN
            RAISE EXCEPTION 'Dilekçe kontrolü devam ederken kaynak iş kapatılamaz.';
        END IF;

        IF NEW.task_type_id = '83' THEN
            IF NEW.status = 'completed'
               AND COALESCE(NEW.details ->> 'review_result', 'pending') NOT IN ('approved','revision_requested') THEN
                RAISE EXCEPTION 'Dilekçe Kontrol işi yalnız Onayla veya Düzeltme İste aksiyonuyla tamamlanabilir.';
            END IF;

            IF NEW.status NOT IN ('open','in-progress','completed') THEN
                RAISE EXCEPTION 'Dilekçe Kontrol işinin durumu normal iş akışından kapatılamaz.';
            END IF;
        END IF;
    END IF;

    IF OLD.task_type_id IN ('1','7','19','20','37','38','39')
       AND COALESCE(OLD.details ->> 'petition_review_status', '') = 'in_review'
       AND NEW.task_owner_id IS DISTINCT FROM OLD.task_owner_id THEN
        RAISE EXCEPTION 'Dilekçe kontrolü devam ederken kaynak işin task_owner_id bilgisi değiştirilemez.';
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.trg_on_task_delete_cleanup()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    -- A) Bu göreve bağlı TAHAKKUKLARI (accruals) sil
    DELETE FROM accruals WHERE task_id = OLD.id;

    -- B) Bu göreve bağlı DAVA KAYITLARINI (suits) sil
    DELETE FROM suits WHERE task_id = OLD.id;

    -- C) Bu göreve bağlı TRANSACTION GEÇMİŞİNİ SİL (Hiyerarşik Silme)
    DELETE FROM transactions WHERE parent_id IN (
        SELECT id FROM transactions WHERE task_id = OLD.id
    );
    DELETE FROM transactions WHERE task_id = OLD.id;

    -- D) Bu göreve bağlı BİLDİRİMLERİ (mail_notifications) güncelle/sil
    UPDATE mail_notifications 
    SET associated_task_id = NULL 
    WHERE associated_task_id = OLD.id AND status = 'sent';

    DELETE FROM mail_notifications 
    WHERE associated_task_id = OLD.id AND status != 'sent';

    -- E) ALT GÖREVLERİ SİL (details->>'parent_task_id' kontrolü ile)
    DELETE FROM tasks WHERE details->>'parent_task_id' = OLD.id;

    -- 🔥 F) GÖREV GEÇMİŞİNİ SİLMEK YERİNE, "SİLİNDİ" LOGU EKLİYORUZ
    -- Eski 'DELETE FROM task_history...' satırını kaldırdık!
    
    INSERT INTO public.task_history (
        task_id,
        action,
        user_id,
        details
    ) VALUES (
        OLD.id,
        'task_deleted',
        auth.uid(), -- Supabase üzerinden işlemi yapan kullanıcının ID'sini otomatik çeker
        jsonb_build_object(
            'note', 'Görev sistemden silindi.',
            'task_title', OLD.title,
            'task_type_id', OLD.task_type_id,
            'ip_record_id', OLD.ip_record_id,
            'deleted_at', NOW()
        )
    );

    -- G) GÖREVE EKLENEN BELGELERİ SİL (task_documents)
    DELETE FROM task_documents WHERE task_id = OLD.id;

    -- İşlemi tamamla ve devam et
    RETURN OLD;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_monitoring_record_parent()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    -- monitored_trademark_id boş bırakılmışsa mevcut nullable davranışı koru.
    IF NEW.monitored_trademark_id IS NULL THEN
        RETURN NEW;
    END IF;

    IF NEW.monitoring_type = 'domestic' THEN
        IF NOT EXISTS (
            SELECT 1
            FROM public.monitoring_trademarks mt
            WHERE mt.id::text = NEW.monitored_trademark_id::text
        ) THEN
            RAISE EXCEPTION
                'Domestic monitoring record not found: %',
                NEW.monitored_trademark_id
                USING ERRCODE = '23503';
        END IF;

    ELSIF NEW.monitoring_type = 'international' THEN
        IF NOT EXISTS (
            SELECT 1
            FROM public.international_monitoring im
            WHERE im.id::text = NEW.monitored_trademark_id::text
        ) THEN
            RAISE EXCEPTION
                'International monitoring record not found: %',
                NEW.monitored_trademark_id
                USING ERRCODE = '23503';
        END IF;

    ELSE
        RAISE EXCEPTION
            'Invalid monitoring_type: %', NEW.monitoring_type
            USING ERRCODE = '23514';
    END IF;

    RETURN NEW;
END;
$function$
